import sys

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        P = sys.stdin.readline().strip()
        n = len(P)
        days = 0
        max_jump = 1
        i = 0
        while i < n:
            if P[i] == '#':
                i += 1
            else:
                j = i
                while j < n and P[j] == '.':
                    j += 1
                required_jump = j - i
                if required_jump > max_jump:
                    days += 1
                    max_jump = required_jump
                i = j
        print(days)

solve()
